import{_ as a,o as r,c as l,a2 as e}from"./chunks/framework.DSoq407f.js";const g=JSON.parse('{"title":"核心特性","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features.md","filePath":"guide/features.md","lastUpdated":1786505997000}'),i={name:"guide/features.md"};function o(s,t,n,d,h,u){return r(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h1><blockquote><p><strong>你会了解到</strong>：V3 的核心优势，以及每项能力背后的设计思路。</p></blockquote><h2 id="一、多租户-saas-架构" tabindex="-1">一、多租户 SaaS 架构 <a class="header-anchor" href="#一、多租户-saas-架构" aria-label="Permalink to &quot;一、多租户 SaaS 架构&quot;">​</a></h2><p>V3 从第一天就按<strong>多租户</strong>设计：一套部署，服务无数客户。</p><ul><li>每个客户（租户）有独立的机器人实例、插件配置、订阅、余额。</li><li>数据按租户隔离，A 客户绝对看不到 B 客户的任何数据。</li><li>所有租户共享同一套适配器和插件市场，但各自的运行时互不干扰。</li></ul><div class="tip custom-block"><p class="custom-block-title">为什么重要</p><p>传统&quot;一客一套&quot;模式，运维成本随客户数线性增长。多租户让你用一套系统的运维成本，服务成百上千个客户。</p></div><h2 id="二、插件市场与开发者生态" tabindex="-1">二、插件市场与开发者生态 <a class="header-anchor" href="#二、插件市场与开发者生态" aria-label="Permalink to &quot;二、插件市场与开发者生态&quot;">​</a></h2><p>V3 内置完整的<strong>插件交易市场</strong>：</p><ul><li><strong>开发者中心</strong>：第三方开发者注册成为开发者，上传插件、管理版本。</li><li><strong>定价上架</strong>：插件可免费或付费，开发者自主定价。</li><li><strong>收益分成</strong>：客户购买插件的收入，按平台与开发者的分成比例结算，开发者可提现。</li><li><strong>审核机制</strong>：平台管理员审核上架的插件，把控质量与安全。</li><li><strong>一次编写，处处运行</strong>：插件基于 <a href="./../xubp/overview">XUBP 协议</a> 开发，同一份代码在所有平台通用。</li></ul><h2 id="三、订阅与计费体系" tabindex="-1">三、订阅与计费体系 <a class="header-anchor" href="#三、订阅与计费体系" aria-label="Permalink to &quot;三、订阅与计费体系&quot;">​</a></h2><p>完整的商业化闭环：</p><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>订阅套餐</td><td>支持月付、年付、永久、自定义；按套餐分配机器人数量、插件数量等配额</td></tr><tr><td>卡密系统</td><td>生成套餐卡、余额卡、插件卡，客户用卡密兑换</td></tr><tr><td>余额充值</td><td>预设充值档位 + 自定义金额，余额可购买插件、续订</td></tr><tr><td>支付集成</td><td>内置彩虹易支付，支持 V1 / V2 协议</td></tr><tr><td>配额管控</td><td>订阅过期自动降级资源（不删数据），续费即恢复</td></tr></tbody></table><h2 id="四、分布式适配器架构" tabindex="-1">四、分布式适配器架构 <a class="header-anchor" href="#四、分布式适配器架构" aria-label="Permalink to &quot;四、分布式适配器架构&quot;">​</a></h2><p>每个平台适配器和每个插件都以<strong>独立子进程</strong>运行：</p><ul><li><strong>故障隔离</strong>：一个插件崩溃，不会拖垮其他插件或主进程。</li><li><strong>自动恢复</strong>：进程崩溃后可配置自动重启；父进程退出时子进程安全退出。</li><li><strong>可靠投递</strong>：事件通过持久化队列传递，保证不丢失；Redis 不可用时自动降级。</li><li><strong>可扩展</strong>：适配器支持多节点，应对高并发场景。</li></ul><p>详见 <a href="./architecture">系统架构</a>。</p><h2 id="五、rbac-权限与审计" tabindex="-1">五、RBAC 权限与审计 <a class="header-anchor" href="#五、rbac-权限与审计" aria-label="Permalink to &quot;五、RBAC 权限与审计&quot;">​</a></h2><p>三套独立角色，权限粒度到每个操作：</p><ul><li><strong>管理后台</strong>：平台级管理——用户、适配器、市场、订阅、开发者、内容、设置、审计。</li><li><strong>用户控制台</strong>：租户自助——创建机器人、装插件、管理订阅、充值。</li><li><strong>开发者中心</strong>：插件开发者——上传插件、看销量、提现。</li></ul><div class="warning custom-block"><p class="custom-block-title">全操作审计</p><p>管理后台和用户控制台的<strong>所有关键操作都会记录审计日志</strong>，谁在什么时候做了什么，全程可追溯。</p></div><h2 id="六、在线更新" tabindex="-1">六、在线更新 <a class="header-anchor" href="#六、在线更新" aria-label="Permalink to &quot;六、在线更新&quot;">​</a></h2><ul><li>后台一键检测云端新版本。</li><li>增量下载更新包，只替换变化的文件。</li><li>更新完成后自动重启服务（可配置），无需 SSH 登录服务器。</li><li>支持 SQL 迁移脚本随版本一起执行。</li></ul><h2 id="七、域名授权保护" tabindex="-1">七、域名授权保护 <a class="header-anchor" href="#七、域名授权保护" aria-label="Permalink to &quot;七、域名授权保护&quot;">​</a></h2><p>V3 是闭源商业产品，采用<strong>域名绑定授权</strong>：</p><ul><li>每个部署实例绑定到一个域名，云端定期校验授权有效性。</li><li>授权码可在安装时根据访问域名<strong>自动获取</strong>，无需手动查找。</li><li>离线/断网时使用本地加密缓存，网络恢复后自动同步。</li></ul><p>详见 <a href="./../deploy/authorization">授权激活</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>想看整体怎么运转 → <a href="./architecture">系统架构</a></li><li>想动手部署 → <a href="./../deploy/requirements">环境要求</a></li></ul>',28)])])}const p=a(i,[["render",o]]);export{g as __pageData,p as default};
